/* ChartPulse — Shared Styles */
:root {
  --bg-primary: #0f0f1a;
  --bg-secondary: #151527;
  --bg-card: #1a1a2e;
  --bg-hover: #1e1e35;
  --bg-input: #12121f;
  --border: #2a2a45;
  --border-light: #333355;
  --accent-blue: #2962ff;
  --accent-blue-hover: #3d70ff;
  --accent-green: #26a69a;
  --gain: #26a69a;
  --loss: #ef5350;
  --gain-bg: rgba(38,166,154,0.12);
  --loss-bg: rgba(239,83,80,0.12);
  --text-primary: #e8e8f0;
  --text-secondary: #8888aa;
  --text-muted: #555577;
  --gold: #f5c842;
  --platinum: #a0b0c8;
  --font: 'Inter', 'DM Sans', system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  line-height: 1.5;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: var(--font); }

/* ---- NAV ---- */
.nav {
  display: flex;
  align-items: center;
  padding: 0 20px;
  height: 52px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 100;
  gap: 0;
}

.nav-logo {
  font-size: 17px;
  font-weight: 700;
  color: var(--accent-blue);
  letter-spacing: -0.5px;
  margin-right: 32px;
  white-space: nowrap;
}
.nav-logo span { color: var(--text-primary); }

.nav-links {
  display: flex;
  gap: 4px;
  flex: 1;
}

.nav-link {
  padding: 6px 12px;
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 500;
  transition: all 0.15s;
  white-space: nowrap;
}
.nav-link:hover, .nav-link.active {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.nav-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-left: auto;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  border: none;
  transition: all 0.15s;
}
.btn-ghost {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border);
}
.btn-ghost:hover { color: var(--text-primary); border-color: var(--border-light); background: var(--bg-hover); }
.btn-primary {
  background: var(--accent-blue);
  color: #fff;
}
.btn-primary:hover { background: var(--accent-blue-hover); }
.btn-sm { padding: 5px 12px; font-size: 12px; }

/* ---- TICKER BAR ---- */
.ticker-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  padding: 0 20px;
  height: 36px;
  display: flex;
  align-items: center;
  gap: 0;
  overflow: hidden;
}

.ticker-tabs {
  display: flex;
  gap: 0;
  height: 100%;
  margin-right: 16px;
  flex-shrink: 0;
}

.ticker-tab {
  padding: 0 14px;
  height: 100%;
  display: flex;
  align-items: center;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
}
.ticker-tab:hover { color: var(--text-primary); }
.ticker-tab.active {
  color: var(--accent-blue);
  border-bottom-color: var(--accent-blue);
}

.ticker-items {
  display: flex;
  gap: 24px;
  overflow: hidden;
}

.ticker-item {
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.ticker-name { color: var(--text-secondary); font-size: 12px; }
.ticker-price { color: var(--text-primary); font-size: 12px; font-weight: 600; }
.badge {
  padding: 2px 6px;
  border-radius: 4px;
  font-size: 11px;
  font-weight: 600;
}
.badge-gain { background: var(--gain-bg); color: var(--gain); }
.badge-loss { background: var(--loss-bg); color: var(--loss); }
.badge-neutral { background: rgba(136,136,170,0.12); color: var(--text-secondary); }

/* ---- TABS ---- */
.tabs {
  display: flex;
  gap: 0;
  border-bottom: 1px solid var(--border);
}
.tab {
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  cursor: pointer;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  transition: all 0.15s;
  white-space: nowrap;
}
.tab:hover { color: var(--text-primary); }
.tab.active {
  color: var(--text-primary);
  border-bottom-color: var(--accent-blue);
}

/* ---- SECTION ---- */
.section { padding: 32px 20px; max-width: 1400px; margin: 0 auto; }
.section-sm { padding: 20px 20px; max-width: 1400px; margin: 0 auto; }
.section-title {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 16px;
  color: var(--text-primary);
}
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

/* ---- CARDS ---- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 16px;
}
.card:hover { border-color: var(--border-light); }

/* ---- GRID ---- */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

/* ---- TABLE ---- */
.data-table {
  width: 100%;
  border-collapse: collapse;
}
.data-table th {
  padding: 8px 10px;
  text-align: left;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  border-bottom: 1px solid var(--border);
}
.data-table th:last-child, .data-table td:last-child { text-align: right; }
.data-table td {
  padding: 9px 10px;
  font-size: 12px;
  border-bottom: 1px solid var(--border);
  color: var(--text-primary);
}
.data-table tr:last-child td { border-bottom: none; }
.data-table tr:hover td { background: var(--bg-hover); }

/* ---- SPARKLINE (SVG) ---- */
.sparkline { display: block; }

/* ---- GAIN/LOSS TEXT ---- */
.gain { color: var(--gain); }
.loss { color: var(--loss); }
.neutral { color: var(--text-secondary); }

/* ---- FOOTER ---- */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 40px 20px 24px;
  margin-top: 60px;
}
.footer-grid {
  max-width: 1400px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1.5fr repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 32px;
}
.footer-logo {
  font-size: 18px;
  font-weight: 700;
  color: var(--accent-blue);
  margin-bottom: 10px;
}
.footer-logo span { color: var(--text-primary); }
.footer-tagline { color: var(--text-secondary); font-size: 12px; line-height: 1.6; }
.footer-col h4 {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: var(--text-muted);
  margin-bottom: 12px;
}
.footer-col a {
  display: block;
  color: var(--text-secondary);
  font-size: 12px;
  margin-bottom: 8px;
  transition: color 0.15s;
}
.footer-col a:hover { color: var(--text-primary); }
.footer-bottom {
  max-width: 1400px;
  margin: 0 auto;
  padding-top: 24px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.footer-bottom p { color: var(--text-muted); font-size: 11px; }

/* ---- SCROLLBAR ---- */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border-light); border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* ---- RESPONSIVE ---- */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: 1fr; }
}

