<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AAPL Chart — ChartPulse</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/remixicon/4.2.0/remixicon.min.css">
<link rel="stylesheet" href="styles.css">
<style>
body { overflow: hidden; height: 100vh; display: flex; flex-direction: column; }

/* CHART TOOLBAR */
.chart-toolbar {
  height: 44px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  padding: 0 12px;
  gap: 4px;
  flex-shrink: 0;
  overflow-x: auto;
}
.tool-btn {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 16px;
  border: none;
  background: none;
  transition: all 0.15s;
  cursor: pointer;
  flex-shrink: 0;
}
.tool-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
.tool-btn.active { color: var(--accent-blue); background: rgba(41,98,255,0.12); }
.tool-sep { width: 1px; height: 24px; background: var(--border); margin: 0 4px; flex-shrink: 0; }
.symbol-display {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border-right: 1px solid var(--border);
  margin-right: 8px;
}
.symbol-name { font-size: 14px; font-weight: 700; }
.symbol-price { font-size: 14px; font-weight: 600; }
.symbol-change { font-size: 13px; }

/* TIME BUTTONS */
.timeframe-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-left: auto;
}
.tf-btn {
  padding: 4px 8px;
  border-radius: 5px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  border: none;
  background: none;
  cursor: pointer;
  transition: all 0.15s;
}
.tf-btn:hover { color: var(--text-primary); background: var(--bg-hover); }
.tf-btn.active { color: var(--text-primary); background: var(--bg-hover); }

/* MAIN LAYOUT */
.chart-layout {
  display: flex;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

/* WATCHLIST SIDEBAR */
.watchlist {
  width: 240px;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  overflow: hidden;
}
.watchlist-header {
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 8px;
}
.watchlist-search {
  flex: 1;
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 5px 8px;
  color: var(--text-primary);
  font-size: 12px;
  font-family: var(--font);
  outline: none;
}
.watchlist-search:focus { border-color: var(--accent-blue); }
.watchlist-body { flex: 1; overflow-y: auto; }
.wl-category {
  border-bottom: 1px solid var(--border);
}
.wl-cat-header {
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  user-select: none;
  transition: background 0.1s;
}
.wl-cat-header:hover { background: var(--bg-hover); }
.wl-cat-name {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}
.wl-cat-arrow { color: var(--text-muted); font-size: 12px; transition: transform 0.2s; }
.wl-cat-arrow.open { transform: rotate(90deg); }
.wl-items { overflow: hidden; }
.wl-item {
  padding: 7px 12px;
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 6px;
  align-items: center;
  cursor: pointer;
  transition: background 0.1s;
}
.wl-item:hover, .wl-item.active { background: var(--bg-hover); }
.wl-item.active .wl-sym { color: var(--accent-blue); }
.wl-sym { font-size: 12px; font-weight: 700; }
.wl-price { font-size: 12px; font-weight: 600; text-align: right; }
.wl-chg { font-size: 11px; font-weight: 600; text-align: right; white-space: nowrap; }

/* CHART AREA */
.chart-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
}
.chart-canvas-area {
  flex: 1;
  position: relative;
  overflow: hidden;
  background: var(--bg-primary);
}
.chart-svg { width: 100%; height: 100%; }
.price-label {
  position: absolute;
  right: 8px;
  padding: 2px 6px;
  background: var(--loss);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  border-radius: 3px;
  white-space: nowrap;
}

/* DETAIL PANEL */
.detail-panel {
  width: 300px;
  background: var(--bg-secondary);
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  flex-shrink: 0;
}
.detail-header {
  padding: 14px 16px;
  border-bottom: 1px solid var(--border);
}
.detail-ticker { font-size: 18px; font-weight: 800; color: var(--text-primary); }
.detail-company { font-size: 12px; color: var(--text-secondary); margin-top: 1px; }
.detail-exchange { font-size: 11px; color: var(--text-muted); }
.detail-price-row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  margin-top: 10px;
}
.detail-price { font-size: 26px; font-weight: 800; }
.detail-change { font-size: 14px; font-weight: 600; }

.detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
}
.detail-stat {
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
}
.detail-stat:nth-child(odd) { border-right: 1px solid var(--border); }
.detail-stat-label { font-size: 10px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 3px; }
.detail-stat-val { font-size: 13px; font-weight: 600; }

.news-headline {
  padding: 12px 16px;
  border-bottom: 1px solid var(--border);
  font-size: 11px;
  color: var(--text-secondary);
  line-height: 1.5;
}
.news-headline strong { color: var(--text-primary); }

.premarket-bar {
  padding: 10px 16px;
  background: rgba(38,166,154,0.06);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.premarket-label { font-size: 11px; color: var(--text-muted); }
.premarket-val { font-size: 13px; font-weight: 700; color: var(--gain); }

/* FINANCIALS SECTION */
.fin-section {
  border-top: 1px solid var(--border);
}
.fin-section-title {
  padding: 10px 16px 6px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--text-muted);
}
.fin-row {
  padding: 7px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border);
  font-size: 12px;
}
.fin-row:last-child { border-bottom: none; }
.fin-label { color: var(--text-secondary); }
.fin-val { font-weight: 600; color: var(--text-primary); }

/* ANNUAL/QUARTERLY TABS */
.detail-tabs {
  display: flex;
  padding: 8px 16px 0;
  gap: 0;
  border-bottom: 1px solid var(--border);
}
.detail-tab {
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
  border-bottom: 2px solid transparent;
  cursor: pointer;
  background: none;
  border-top: none; border-left: none; border-right: none;
  transition: all 0.15s;
}
.detail-tab.active { color: var(--text-primary); border-bottom-color: var(--accent-blue); }
.detail-tab:hover { color: var(--text-primary); }

.perf-row {
  padding: 7px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--border);
  font-size: 12px;
}
.perf-bar {
  height: 4px;
  border-radius: 2px;
  background: var(--gain);
  display: inline-block;
  vertical-align: middle;
  margin-left: 8px;
}

@media (max-width: 1024px) {
  .watchlist { width: 200px; }
  .detail-panel { width: 260px; }
}
@media (max-width: 768px) {
  .watchlist, .detail-panel { display: none; }
}
</style>
</head>
