<script>
// Watchlist data
const watchlistData = [
  { cat: 'Indices', icon: 'ri-global-line', items: [
    {sym:'SPX', price:'7,041.29', chg:'+0.26%', up:true},
    {sym:'NDQ', price:'26,333.00', chg:'+0.49%', up:true},
    {sym:'DJI', price:'48,578.72', chg:'+0.24%', up:true},
    {sym:'VIX', price:'17.86', chg:'−0.45%', up:false},
  ]},
  { cat: 'Stocks', icon: 'ri-stock-line', items: [
    {sym:'AAPL', price:'263.40', chg:'−1.14%', up:false, active:true},
    {sym:'TSLA', price:'388.90', chg:'−0.78%', up:false},
    {sym:'NFLX', price:'107.79', chg:'+0.07%', up:true},
  ]},
  { cat: 'Futures', icon: 'ri-oil-line', items: [
    {sym:'USOIL', price:'87.53', chg:'−6.06%', up:false},
    {sym:'GOLD', price:'4,801.92', chg:'+0.30%', up:true},
  ]},
  { cat: 'Forex', icon: 'ri-exchange-dollar-line', items: [
    {sym:'EURUSD', price:'1.17949', chg:'+0.12%', up:true},
    {sym:'GBPUSD', price:'1.35335', chg:'+0.06%', up:true},
  ]},
  { cat: 'Crypto', icon: 'ri-bit-coin-line', items: [
    {sym:'BTCUSD', price:'75,585', chg:'+0.54%', up:true},
    {sym:'ETHUSD', price:'2,355.1', chg:'+0.25%', up:true},
  ]},
];

const openCats = new Set(['Indices','Stocks','Futures','Forex','Crypto']);

function renderWatchlist() {
  const body = document.getElementById('watchlist-body');
  body.innerHTML = watchlistData.map(cat => {
    const isOpen = openCats.has(cat.cat);
    return `
    <div class="wl-category">
      <div class="wl-cat-header" onclick="toggleCat('${cat.cat}')">
        <span class="wl-cat-name"><i class="${cat.icon}"></i>${cat.cat}</span>
        <i class="ri-arrow-right-s-line wl-cat-arrow ${isOpen ? 'open' : ''}" id="arrow-${cat.cat}"></i>
      </div>
      <div class="wl-items" id="cat-${cat.cat}" style="${isOpen ? '' : 'display:none;'}">
        ${cat.items.map(item => `
        <div class="wl-item ${item.active ? 'active' : ''}" onclick="selectSymbol('${item.sym}')">
          <span class="wl-sym">${item.sym}</span>
          <span class="wl-price">${item.price}</span>
          <span class="wl-chg ${item.up ? 'gain' : 'loss'}">${item.chg}</span>
        </div>`).join('')}
      </div>
    </div>`;
  }).join('');
}

function toggleCat(cat) {
  if (openCats.has(cat)) {
    openCats.delete(cat);
  } else {
    openCats.add(cat);
  }
  renderWatchlist();
}

function selectSymbol(sym) { /* would load new chart */ }

// Generate candlestick chart
function drawChart() {
  const canvas = document.getElementById('chart-canvas');
  const svgEl = document.getElementById('chart-svg');
  const W = canvas.offsetWidth;
  const H = canvas.offsetHeight;
  svgEl.setAttribute('viewBox', `0 0 ${W} ${H}`);

  const priceMin = 220, priceMax = 290;
  const numCandles = Math.floor((W - 60) / 10);
  const candleWidth = 7;
  const spacing = Math.floor((W - 60) / numCandles);
  const volHeight = 40;
  const chartH = H - volHeight - 20;
  const priceRange = priceMax - priceMin;

  function py(price) { return chartH - ((price - priceMin) / priceRange * chartH); }

  let candles = [];
  let price = 253;
  for (let i = 0; i < numCandles; i++) {
    const open = price + (Math.random() - 0.48) * 3;
    const close = open + (Math.random() - 0.48) * 4;
    const high = Math.max(open, close) + Math.random() * 2;
    const low = Math.min(open, close) - Math.random() * 2;
    price = close;
    candles.push({ open, close, high, low, vol: 0.3 + Math.random() * 0.7 });
  }
  // Force last price near 263.40
  candles[candles.length - 1].close = 263.40;

  const candlesG = document.getElementById('candles');
  const volG = document.getElementById('volume-bars');
  candlesG.innerHTML = '';
  volG.innerHTML = '';

  candles.forEach((c, i) => {
    const x = 8 + i * spacing + spacing / 2;
    const isUp = c.close >= c.open;
    const color = isUp ? '#26a69a' : '#ef5350';
