<script>
let currentCat = 'all';
let currentSort = 'rated';

const ratingOrder = { 'OKX': 4.9, 'AMP': 4.6, 'moomoo': 4.6, 'OANDA': 4.5, 'FOREX.com': 4.5, 'TradeStation': 4.3, 'Interactive Brokers': 4.2 };

function filterBrokers(cat, btn) {
  currentCat = cat;
  document.querySelectorAll('.broker-cat-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  applyFilters();
}

function sortBrokers(btn, sort) {
  currentSort = sort;
  document.querySelectorAll('.sort-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  applyFilters();
}

function applyFilters() {
  const cards = Array.from(document.querySelectorAll('.broker-card'));
  let visible = cards.filter(card => {
    if (currentCat === 'all') return true;
    const cats = card.dataset.cats || '';
    return cats.split(',').includes(currentCat);
  });

  if (currentSort === 'rated') {
    visible.sort((a, b) => {
      const ra = parseFloat(a.querySelector('.broker-rating-big').textContent) || 0;
      const rb = parseFloat(b.querySelector('.broker-rating-big').textContent) || 0;
      return rb - ra;
    });
  }

  const container = document.getElementById('broker-listings');
  cards.forEach(c => c.style.display = 'none');

  visible.forEach(card => {
    card.style.display = '';
    container.appendChild(card);
  });

  document.getElementById('broker-count').textContent = `Showing ${visible.length} broker${visible.length !== 1 ? 's' : ''}`;
}
</script>
